MOD = 61
N_L = {k: 0 for k in range(MOD)}

for a in range(MOD):
    for b in range(MOD):
        k = (a*a + b*b) % MOD
        N_L[k] += 1

print("N_L(k) for k in {0, ..., 60}:")
for k in range(MOD):
    print(f"k={k}: {N_L[k]}")

# Verify the total count
total_count = sum(N_L.values())
print(f"Total count: {total_count}")
